import{_ as o,l as s,o as e,c as r,v as i,p as n,x as t,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"扩散蒸馏与少步","description":"","frontmatter":{"title":"扩散蒸馏与少步","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diffusion-distillation.md","filePath":"llm/diffusion-distillation.md","lastUpdated":1789023840000}'),h={name:"llm/diffusion-distillation.md"};function c(f,a,_,u,A,D){const l=s("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="扩散蒸馏与少步" tabindex="-1">扩散蒸馏与少步 <a class="header-anchor" href="#扩散蒸馏与少步" aria-label="Permalink to &quot;扩散蒸馏与少步&quot;">​</a></h1><div class="epigraph"><p>多步采样买的是沿向量场慢慢走。蒸馏把多步教师压成少步学生，用质量换延迟。</p><footer>—— Salimans, Ho, Progressive Distillation；Song 等 Consistency Models</footer></div><p><a href="/llm/transfusion">上一课</a>仍可能对图像槽走完整扩散链。<a href="/llm/ddpm">DDPM</a> 的 \\(T\\) 是税。缺口是少步：推理要 1–8 步而不是 50–1000。后课视频默认：每帧再乘时间，少步从可选变成必要。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐步去噪或 ODE 积分在每步调用同一骨干。交互式文生图、统一模型里的「边说边画」负担不起。渐进蒸馏：把 \\(N\\) 步教师蒸馏成 \\(N/2\\) 步学生，反复直到很少步。一致性模型学从任意 \\(t\\) 一步（或少步）映射到数据，自洽于教师轨迹。还有分布匹配蒸馏（学生样本匹配教师分布）等变体。</p><p>少步不是新的物理：是用额外训练把轨迹缩短。教师若本身贴不住条件，学生会把 CFG 伪影一起学会。</p><p><span class="marginnote">1 步生成接近 GAN 的延迟，也接近 GAN 的失败：模式崩、过饱和。少步模型要单独评，不能只报教师 FID。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先训好多步教师（可含 <a href="/llm/cfg-image">CFG</a>），再按选定蒸馏目标训学生。推理固定步数与日程。验收：FID、条件遵守、文字，以及步数–质量曲线。不要用理解基准（VQA）代替生成少步评测。</p>',9)),(e(),n(m,null,{default:t(()=>[p(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20TCH%5B%22%E5%A4%9A%E6%AD%A5%E6%95%99%E5%B8%88%22%5D%20--%3E%20DST%5B%22%E8%92%B8%E9%A6%8F%22%5D%0A%20%20DST%20--%3E%20STU%5B%22%E5%B0%91%E6%AD%A5%E5%AD%A6%E7%94%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>教师轨迹定义从噪声到数据的曲线。学生若只拟合端点，中间可走歪；一致性则约束任意时刻输出一致。渐进蒸馏保持逐步语义，每代步数减半，误差会累积，所以教师要够强、日程要对齐。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>蒸馏不提高 VAE 重构上限。下一课把生成从单帧扩到时空，步数与记忆同时涨。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>少步靠蒸馏或一致性，不是改一句采样器配置。</li><li>学生会继承教师的 CFG 与伪影。</li><li>必须单独报步数–质量，不能只抄教师 FID。</li><li>出处：Salimans &amp; Ho Progressive Distillation；Song 等 Consistency Models。</li></ul>',6))])}const S=o(h,[["render",c]]);export{E as __pageData,S as default};
